<header class="admin-page-head"><div><p class="eyebrow">Customer requests</p><h1>Enquiries</h1></div></header><section class="admin-panel"><div class="admin-table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Status</th><th>Requested</th><th>Fulfilment</th><th>Received</th><th></th></tr></thead><tbody><?php foreach($enquiries as $item): ?><tr><td><?= e($item['reference']) ?></td><td><?= e($item['customer_name']) ?><small><?= e($item['customer_phone']) ?></small></td><td><span class="status-badge"><?= e($item['status']) ?></span></td><td><?= e($item['requested_date']) ?></td><td><?= e(ucfirst($item['fulfilment_method'])) ?></td><td><?= e($item['created_at']) ?></td><td><a href="/admin/enquiries/<?= (int)$item['id'] ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$enquiries): ?><div class="empty-state compact"><p>No enquiries yet.</p></div><?php endif; ?></section>
